'use strict';
let droppedMediaBusy=false;
function droppedFileKind(file){if(/^image\/(png|jpeg|webp|gif)$/i.test(file.type)||!file.type&&/\.(png|jpe?g|webp|gif)$/i.test(file.name))return'image';if(/^video\//.test(file.type)||!file.type&&/\.(mp4|webm|mov|ogv)$/i.test(file.name))return'video';if(/^audio\//.test(file.type)||!file.type&&/\.(wav|mp3|m4a|aac|ogg|flac)$/i.test(file.name))return'audio';return null}
async function importDroppedFiles(files,{at=globalTime(),point=null,role='effect'}={}){if(recording||droppedMediaBusy||videoImportBusy||audioBusy||window.editorTaskBusy)throw Error('Finish the current media task before dropping files.');if(!files.length)return[];if(files.length>20)throw Error('Drop up to 20 files at a time.');stop();if(pathEditor)finishPathEditing();seekGlobal(clamp(at,0,totalDuration()-.1));const owner=project,target=current(),results=[],failed=[];droppedMediaBusy=true;window.editorTaskBusy=true;try{for(const file of files){if(project!==owner||current()!==target)throw Error('The project changed during import.');const kind=droppedFileKind(file);if(!kind){failed.push(file.name+': unsupported file');continue}try{const ids=new Set(current().objects.map(o=>o.id)),audioIds=new Set(tracks().map(c=>c.id));if(kind==='image'){if(file.size>16e6)throw Error('image exceeds 16 MB');const source=await dataURL(file),image=await imageReady(source);if(project!==owner||current()!==target)throw Error('The project changed during import.');if(!image.naturalWidth)throw Error('image could not load');let src=source;if(file.size>3e6||image.width>4096||image.height>4096){const scale=Math.min(1,4096/image.width,4096/image.height),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);src=canvas.toDataURL('image/png');if(src.length>8e6)throw Error('image is too complex; resize it first')}const o=newObject('image',{name:file.name,src,in:time,out:current().duration});o.keys=[{t:time,v:{...pose,x:point?.x??480,y:point?.y??270}}];await imageReady(src)}else if(kind==='video')await importVideoFiles([file]);else await importSounds([file],role);const visual=current().objects.filter(o=>!ids.has(o.id)),sound=tracks().filter(c=>!audioIds.has(c.id));if(!visual.length&&!sound.length)throw Error('file could not be decoded or exceeds its size limit');if(point)for(const o of visual)for(const key of o.keys){key.v.x=point.x;key.v.y=point.y}results.push({name:file.name,kind,objects:visual.map(o=>o.id),audio:sound.map(c=>c.id)});if(kind==='audio'){selectLayers([]);selectedAudio=sound.at(-1)?.id||null}}catch(e){failed.push(file.name+': '+e.message)}}save();render();tab('media');if(failed.length)toast(results.length+' imported. '+failed.join(' · '));else toast(results.length+' file'+(results.length===1?'':'s')+' added at '+at.toFixed(2)+'s.');return results}finally{droppedMediaBusy=false;window.editorTaskBusy=false;document.body.classList.remove('media-drop-active')}}
const dropTargets=[document.querySelector('.paperstage'),$('timelineBody')];
for(const target of dropTargets){target.addEventListener('dragover',e=>{if(![...e.dataTransfer.types].includes('Files'))return;e.preventDefault();e.dataTransfer.dropEffect='copy';target.classList.add('media-drop-target')});target.addEventListener('dragleave',e=>{if(!target.contains(e.relatedTarget))target.classList.remove('media-drop-target')});target.addEventListener('drop',async e=>{if(!e.dataTransfer.files.length)return;e.preventDefault();e.stopPropagation();target.classList.remove('media-drop-target');const onTimeline=target===$('timelineBody'),at=onTimeline?clamp((e.clientX-target.getBoundingClientRect().left+target.scrollLeft-timelineLabelWidth())/timelineZoom,0,totalDuration()-.1):globalTime(),point=onTimeline?null:pointerWorld(e,null);try{await importDroppedFiles([...e.dataTransfer.files],{at,point})}catch(error){toast(error.message)}})}
// Prevent a file missed by the drop zones from navigating away from the project.
document.addEventListener('dragover',e=>{if([...e.dataTransfer.types].includes('Files'))e.preventDefault()});document.addEventListener('drop',e=>{if(e.dataTransfer.files.length)e.preventDefault()});
